+      sizeBytes: sizeBytes,
+      mtimeMs: mtimeMs,
+      variant: variant,
+      context: context,
+    );
+    while (_entries.length > capacity) {
+      _entries.remove(_entries.keys.first);
+    }
+  }
+
+  /// Drops every entry.
+  void clear() => _entries.clear();
+}
