  // wake may start a run while this load walks — the half-loaded agent
  // cannot survive an over-window guard (the goal_builder incident).
  _sessionLoadsInFlight++;
  try {
    return await _loadSessionInner(metadata);
  } finally {
    _sessionLoadsInFlight--;
