+  ResumedContextCache({int capacity = 4})
+    : capacity = capacity < 1 ? 1 : capacity;
+
+  /// Maximum number of sessions kept resident.
+  final int capacity;
+
+  final Map<String, _Entry> _entries = {};
+
+  /// Number of cached sessions.
+  int get length => _entries.length;
