    io.writeln("switched to session '$label' [${_pathBasename(metadata.cwd)}]");
    _replayRestoredHistory(_agent.state.messages, label);
    switchStage('replay');
    _logDiagnostic(
      'boot_stage switch-done ms=${switchSw.elapsedMilliseconds} '
      'sid=${metadata.id}',
