    // own head in TUI mode.
    final width = io.columns > 0 ? io.columns : 80;
    final (entries, firstIndex) = buildReplayEntries(
      messages,
      tui: _useTui,
      width: width,
      dim: _style.dim,
      cwd: _env.cwd,
      home: config.homeDir,
